// ===============================================================================
// DAEMIND SRE - DEDUPLICAÇÃO & SANITIZAÇÃO DE CONTATOS (SHA-256)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

// 1. Extração e normalização de telefone
let rawPhone = (body.cliente_whatsapp || body.telefone || body.phone || body.customer?.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

// 2. Extração de dados da transação
const clienteNome = (body.cliente_nome || body.nome || body.customer?.first_name || 'Cliente').trim();
const email = (body.cliente_email || body.email || body.customer?.email || '').trim().toLowerCase();
const valorTotal = parseFloat(body.valor_total || body.total || body.cart_total || 0);
const checkoutUrl = body.checkout_url || body.link_carrinho || body.cart_url || 'https://minhaloja.com.br/checkout';
const cupomDesconto = body.cupom || 'VOLTA10';
const rawId = body.carrinho_id || body.id || (email + '_' + valorTotal);

// 3. Cálculo de hash de idempotência SHA-256
const dedupHash = crypto.createHash('sha256').update(String(rawId) + '_' + email + '_' + valorTotal).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    carrinho_id_externo: String(rawId),
    cliente_nome: clienteNome,
    whatsapp: rawPhone,
    email: email,
    valor_total: valorTotal,
    checkout_url: checkoutUrl,
    cupom_desconto: cupomDesconto,
    origem: body.origem || 'ecommerce'
  }
}];

